// Nepali texts for the new world (map, round, the idea "Teile": numbers are made of numbers).
// Number words and names of the things are in /shared/lang/ne.js. a, b, c … = number words ("तीन").
// शिविर ४ (vorrat): कथाको एक कदम, संख्या-मेसिन छोटकरीमा, भाग।
const VSTEP = {
  plus: (k) => `अनि मैले थप ${k} पाएँ।`,
  minus: (k) => `अनि मैले ${k} दिएँ।`,
  double: () => "अनि सबै दोब्बर भयो।",
  half: () => "अनि मैले आधा दिएँ।",
  triple: () => "अनि सबै तेब्बर भयो।",
  third: () => "अनि एक तिहाइ मात्र बाँकी रह्यो।",
  halfminus: (k) => `अनि मैले आधा र थप ${k} दिएँ।`,
  part: (k) => `अनि ${{ "३": "एक तिहाइ", "४": "एक चौथाइ", "५": "एक पाँचौँ भाग" }[k]} गयो।`,
};
const vSteps = (ops) => ops.map((o) => VSTEP[o.type](o.k)).join(" ");
const VSHORT = {
  plus: (k) => `+ ${k}`, minus: (k) => `− ${k}`, double: () => "× २", half: () => "÷ २", triple: () => "× ३", third: () => "÷ ३",
  halfminus: (k) => `÷ २, अनि − ${k}`, part: (k, rest) => `÷ ${k}, अनि × ${rest}`,
};
const VPART = { 2: "आधा", 4: "एक चौथाइ", 8: "एक आठौँ भाग", 16: "एक सोह्रौँ भाग" };

// शिविर ५ (ameisen): हप्ताका दिन, सलाईका काँटीका आकृति, काँटी गन्ने अर्को तरिका।
const DAYS = ["सोमबार", "मङ्गलबार", "बुधबार", "बिहीबार", "शुक्रबार", "शनिबार", "आइतबार"];
const AFORM = { quadrate: "वर्गहरूको एउटा लहर", dreiecke: "त्रिभुजहरूको एउटा लहर, पालैपालो माथि र तल", doppel: "एकमाथि अर्को गरी वर्गका दुई लहर" };
const AOTHER = {
  quadrate: (a) => `अर्को तरिकाले गन: बायाँ एउटा काँटी, अनि हरेक वर्गका लागि ३ नयाँ। १ + ३ × ${a.n} = ${a.answer}।`,
  dreiecke: (a) => `अर्को तरिकाले गन: सुरुमा एउटा काँटी, अनि हरेक त्रिभुजका लागि २ नयाँ। १ + २ × ${a.n} = ${a.answer}।`,
  doppel: (a) => `अर्को तरिकाले गन: बायाँ २ काँटी, अनि हरेक स्तम्भका लागि ५ नयाँ। २ + ५ × ${a.n} = ${a.answer}।`,
};

// शिविर ६ (waage): तराजुमा राखिने चीजहरू।
const WN = {
  kuerbis: "फर्सी", apfel: "स्याउ", melone: "खरबुजा", ananas: "भुइँकटहर", orange: "सुन्तला", birne: "नासपाती",
  kiste: "बाकस", buch: "किताब", beutel: "थैली", murmel: "गुच्चा", paket: "पोका", hund: "कुकुर", katze: "बिरालो", hase: "खरायो",
};
const wn = (n, id) => `${n} ${WN[id]}`;
const wList = (ws) => ws.map((w) => `${w} के.जी.`).join(" र ");
const scales = (a, b) => `पहिलो तराजुमा: बायाँ ${wn(a[0], a[1])}, दायाँ ${wn(a[2], a[3])}। दोस्रोमा: बायाँ ${wn(b[0], b[1])}, दायाँ ${wn(b[2], b[3])}। दुवै बराबर छन्।`;

// शिविर ७ (stall): सानो र ठूलो किसिम, अनि के गनिन्छ।
const SSMALL = { stall: "कुखुरा", fahrrad: "साइकल", tische: "४ जनाका टेबल", boote: "२ जनाका डुङ्गा", spinnen: "खपटे कीरा", muenzen: "२ यूरोका सिक्का", gewicht: "कुखुरा" };
const SBIG = { stall: "बाख्रा", fahrrad: "तीनपाङ्ग्रे", tische: "६ जनाका टेबल", boote: "४ जनाका डुङ्गा", spinnen: "माकुरा", muenzen: "५ यूरोका सिक्का", gewicht: "बाख्रा" };
const SWHAT = { stall: "खुट्टा", fahrrad: "पाङ्ग्रा", tische: "कुर्सी", boote: "सिट", spinnen: "खुट्टा", muenzen: "यूरो", gewicht: "के.जी.", quiz: "अङ्क", drei: "खुट्टा" };

// शिविर ८ (tanz): "र" सहितको सूची, काटिएको चेसबोर्ड, बारहरू।
const tList = (xs) => (xs.length < 2 ? xs.join("") : `${xs.slice(0, -1).join(", ")} र ${xs.at(-1)}`);
const TCUT = { opposite: "दुई विपरीत कुना काटिन्छन्।", row: "माथिल्लो लहरका दुवै कुना काटिन्छन्।", neighbour: "एउटा कुना र त्यसको छेउको कोठा काटिन्छ।", one: "एउटा कुना काटिन्छ।" };
const TDAYS = ["सोमबार", "मङ्गलबार", "बुधबार", "बिहीबार", "शुक्रबार", "शनिबार", "आइतबार"];

// शिविर ९ (fels): सानो घनका कति भागमा रङ छ।
const FK = { 0: "कुनै पनि भागमा रङ नभएका", 1: "ठ्याक्कै १ भागमा रङ भएका", 2: "ठ्याक्कै २ भागमा रङ भएका", 3: "ठ्याक्कै ३ भागमा रङ भएका" };
const FFAN = (a) => (a.h === "१" ? "" : ` र ${a.h === "२" ? "एउटा तेर्सो रेखा" : "तेर्सा रेखाहरू"}`);
const FQUAD = (a) => [["ordnung", `आकार अनुसार: ${a.bySize.join(" + ")} = ${a.answer}।`], ["bild", "कागजबाट एउटा वर्ग काट र जालीमाथि सार।"]];

// शिविर १० (socken): बाकसका रङ, "र" सहितको सूची।
const SCOL = { rot: "राता", blau: "निला", gruen: "हरिया", gelb: "पहेँला", lila: "बैजनी", schwarz: "काला" };
const sList = (colors, thing) => `${colors.map(([id, n]) => `${n} ${SCOL[id]}`).reduce((s, x, i, all) => (i === 0 ? x : i === all.length - 1 ? `${s} र ${x}` : `${s}, ${x}`), "")} ${thing}`;
const SEACH = (a) => [["jede", `सबैभन्दा नराम्रो भाग्य: पहिले अरू रङका सबै ${a.others}, सबैभन्दा कम भएको अन्तिममा। अनि एउटा: ${a.answer}।`], ["probe", "सबैभन्दा कम रङले जाँच: त्यो अन्तिममा आए, कति निकालिसकिएको हुन्छ?"]];

// शिविर १२ (mauer): सङ्ख्या पहेलीका संकेतहरू वाक्यमा।
const MCLUE = {
  between: (lo, hi) => `सङ्ख्या ${lo} र ${hi} को बीचमा छ।`,
  div: (d) => `यो ${d} ले भाग जान्छ।`,
  rest: (d, k) => `${d} ले भाग गर्दा ${k} बाँकी रहन्छ।`,
  sum: (s) => `यसका अङ्कहरूको जोड ${s} हो।`,
  even: () => "यो जोर सङ्ख्या हो।",
  odd: () => "यो बिजोर सङ्ख्या हो।",
  bigger: () => "यसको दशको अङ्क एकको अङ्कभन्दा ठूलो छ।",
  smaller: () => "यसको दशको अङ्क एकको अङ्कभन्दा सानो छ।",
};
const mClues = (clues) => clues.map(([k, ...v]) => MCLUE[k](...v)).join(" ");
const MRIDDLE = (a) => [["eingrenzen", `संकेत-संकेत गर्दै काट: सबै संकेतपछि ${a.answer} मात्र बाँकी रहन्छ।`], ["liste", "पहिलो संकेतमा मिल्ने सबै सङ्ख्या लेख। अनि हरेक संकेतले काट्दै जाऊ।"]];

// चुचुरो (gipfel): कमलको भागहरू।
const GPART = { "२": "आधा", "४": "एक चौथाइ", "८": "एक आठौं भाग", "३": "एक तिहाइ", "९": "एक नवौं भाग", "२७": "एक सत्ताइसौं भाग" };

