      schulweg: (a) => [`घरबाट पसलसम्म ${a.x} बाटो छन्। पसलबाट स्कुलसम्म ${a.y} बाटो छन्। म हरेक बिहान पसल हुँदै जान्छु।`, "मसँग स्कुल जाने कति फरक बाटो छन्?"],
      menue: (a) => [`होटलमा ${a.x} किसिमका सुप र ${a.y} किसिमका मुख्य खाना छन्। सबैले एउटा सुप र एउटा मुख्य खाना लिन्छन्।`, "कति फरक थाली बन्छन्?"],
      eis3: (a) => [`आइसक्रिम पसलमा नयाँ: ${a.x} स्वाद, ${a.y} किसिमका कोन वा कप र ${a.z} किसिमका सस। एक गोला, एक सस।`, "अब कति फरक आइसक्रिम छन्?"],
